// Custom FX — DSP (Rust, compiled to wasm32). Same descriptor as the Rune
// starter, so ui.knob('drive') / ui.knob('tone') work unchanged; param()
// receives the id like the Rune file does.
use songbird_vibefx_sdk::kernels::{db_to_gain, Biquad, Shaper};
use songbird_vibefx_sdk::ProgramDescriptor;

songbird_vibefx_sdk::fx! {
    describe: ProgramDescriptor::new("Warm Drive")
        .knob("drive", 0.0, 24.0, 6.0).unit("dB")
        .knob("tone", 200.0, 8000.0, 2000.0).unit("Hz"),

    state: {
        shaper: Shaper = { let mut s = Shaper::new(); s.set_curve("tanh"); s.set_drive(db_to_gain(6.0)); s },
        lp: [Biquad; 2] = [Biquad::new(48000.0), Biquad::new(48000.0)],
        tone: f64 = 2000.0,
        makeup: f32 = 1.0 / 1.25,
    },

    prepare(state, sr, _max_frames) {
        for lp in &mut state.lp {
            lp.set_sample_rate(sr);
            lp.set("lowpass", state.tone, 0.7, 0.0);
        }
    }

    reset(state) {
        for lp in &mut state.lp { lp.reset(); }
    }

    param(state, id, value) {
        match id {
            "drive" => {
                state.shaper.set_drive(db_to_gain(value));
                state.makeup = 1.0 / (1.0 + value / 24.0);
            }
            "tone" => {
                state.tone = value as f64;
                for lp in &mut state.lp { lp.set("lowpass", state.tone, 0.7, 0.0); }
            }
            _ => {}
        }
    }

    process(state, io) {
        let mut ch = 0;
        while ch < io.num_outputs().min(2) {
            let (input, out) = io.io_pair(ch);
            for (o, i) in out.iter_mut().zip(input) { *o = *i; }
            state.shaper.process(out);
            state.lp[ch].process(out);
            for o in out.iter_mut() { *o *= state.makeup; }
            ch += 1;
        }
    }
}

